selector_to_html = {"a[href=\"#pycmplot-resources\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot.resources<a class=\"headerlink\" href=\"#pycmplot-resources\" title=\"Link to this heading\">\uf0c1</a></h1><p>Centralised configuration for external reference files (liftover chain,\ngene-info TSVs).  Paths are resolved from environment variables or the\nbundled <code class=\"docutils literal notranslate\"><span class=\"pre\">pycmplot/data/</span></code> directory; individual paths can be overridden\nby passing a custom <a class=\"reference internal\" href=\"#pycmplot.resources.ResourceConfig\" title=\"pycmplot.resources.ResourceConfig\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">ResourceConfig</span></code></a> instance\nto any function that accepts a <em>resources</em> argument.</p>", "a[href=\"#pycmplot.resources.ResourceConfig.chain_hg18_hg38\"]": "<dt class=\"sig sig-object py\" id=\"pycmplot.resources.ResourceConfig.chain_hg18_hg38\">\n<span class=\"sig-name descname\"><span class=\"pre\">chain_hg18_hg38</span></span><em class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"pre\">str</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></em></dt><dd></dd>", "a[href=\"#pycmplot.resources.ResourceConfig.require\"]": "<dt class=\"sig sig-object py\" id=\"pycmplot.resources.ResourceConfig.require\">\n<span class=\"sig-name descname\"><span class=\"pre\">require</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">attr</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><span class=\"pre\">str</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><span class=\"pre\">str</span></span></span><a class=\"reference internal\" href=\"../_modules/pycmplot/resources.html#ResourceConfig.require\"><span class=\"viewcode-link\"><span class=\"pre\">[source]</span></span></a></dt><dd><p>Return the path for <em>attr</em>, raising a clear <code class=\"xref py py-exc docutils literal notranslate\"><span class=\"pre\">FileNotFoundError</span></code> if the attribute is unset or the path does not exist.</p><p>First checks whether the attribute value is <code class=\"docutils literal notranslate\"><span class=\"pre\">None</span></code>; if so, raises\n<code class=\"xref py py-exc docutils literal notranslate\"><span class=\"pre\">FileNotFoundError</span></code> with a message indicating which environment\nvariable to set.  Then verifies that the resolved path exists on disk,\nfalling back to <code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">importlib.resources.files()</span></code> package-data resolution\nbefore raising if neither succeeds.</p><p class=\"rubric\">Examples</p></dd>", "a[href=\"#pycmplot.resources.ResourceConfig\"]": "<dt class=\"sig sig-object py\" id=\"pycmplot.resources.ResourceConfig\">\n<em class=\"property\"><span class=\"pre\">class</span><span class=\"w\"> </span></em><span class=\"sig-prename descclassname\"><span class=\"pre\">pycmplot.resources.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ResourceConfig</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chain_hg19_hg38:</span> <span class=\"pre\">str</span> <span class=\"pre\">|</span> <span class=\"pre\">None</span> <span class=\"pre\">=</span> <span class=\"pre\">&lt;factory&gt;</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">chain_hg18_hg38:</span> <span class=\"pre\">str</span> <span class=\"pre\">|</span> <span class=\"pre\">None</span> <span class=\"pre\">=</span> <span class=\"pre\">&lt;factory&gt;</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">geneinfo_hg38:</span> <span class=\"pre\">str</span> <span class=\"pre\">|</span> <span class=\"pre\">None</span> <span class=\"pre\">=</span> <span class=\"pre\">&lt;factory&gt;</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">geneinfo_hg19:</span> <span class=\"pre\">str</span> <span class=\"pre\">|</span> <span class=\"pre\">None</span> <span class=\"pre\">=</span> <span class=\"pre\">&lt;factory&gt;</span></span></em><span class=\"sig-paren\">)</span><a class=\"reference internal\" href=\"../_modules/pycmplot/resources.html#ResourceConfig\"><span class=\"viewcode-link\"><span class=\"pre\">[source]</span></span></a></dt><dd><p>Bases: <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">object</span></code></p><p>Paths to external reference files used by pycmplot.</p><p>Dataclass grouping the on-disk resources required by pycmplot:</p><p>All three attributes default to values resolved from environment\nvariables or the bundled <code class=\"docutils literal notranslate\"><span class=\"pre\">pycmplot/data/</span></code> directory via\n<code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">importlib.resources.files()</span></code>. Override individual attributes to use\ncustom file locations.</p><p class=\"rubric\">Examples</p><p>Use all bundled defaults:</p></dd>", "a[href=\"#module-pycmplot.resources\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">pycmplot.resources<a class=\"headerlink\" href=\"#module-pycmplot.resources\" title=\"Link to this heading\">\uf0c1</a></h2><p>Centralised configuration for external reference files that cannot be\nbundled with the package distribution (large gene-info TSVs, liftover\nchain files, etc.).</p>", "a[href=\"#resolution-order\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Resolution order<a class=\"headerlink\" href=\"#resolution-order\" title=\"Link to this heading\">\uf0c1</a></h3><p>Resource paths are resolved in the following priority order for each\nattribute:</p>", "a[href=\"#pycmplot.resources.ResourceConfig.geneinfo_hg19\"]": "<dt class=\"sig sig-object py\" id=\"pycmplot.resources.ResourceConfig.geneinfo_hg19\">\n<span class=\"sig-name descname\"><span class=\"pre\">geneinfo_hg19</span></span><em class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"pre\">str</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></em></dt><dd></dd>", "a[href=\"#pycmplot.resources.ResourceConfig.geneinfo_hg38\"]": "<dt class=\"sig sig-object py\" id=\"pycmplot.resources.ResourceConfig.geneinfo_hg38\">\n<span class=\"sig-name descname\"><span class=\"pre\">geneinfo_hg38</span></span><em class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"pre\">str</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></em></dt><dd></dd>", "a[href=\"#pycmplot.resources.ResourceConfig.chain_hg19_hg38\"]": "<dt class=\"sig sig-object py\" id=\"pycmplot.resources.ResourceConfig.chain_hg19_hg38\">\n<span class=\"sig-name descname\"><span class=\"pre\">chain_hg19_hg38</span></span><em class=\"property\"><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"pre\">str</span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">None</span></em></dt><dd></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: true, theme: 'light-border',

            });
        };
    };
    console.log("tippy tips loaded!");
};
